CREATE OR REPLACE FUNCTION app_private.analytics_approved_results(_org uuid,_start date,_end date) RETURNS TABLE(id uuid,indicator_id uuid,period_start date,period_end date,version integer,snapshot jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.id,s.indicator_id,s.period_start,s.period_end,s.version,s.snapshot FROM public.indicator_reporting_snapshots s WHERE s.organization_id=_org AND public.results_indicator_access(s.indicator_id) AND s.period_start>=_start AND s.period_end<=_end AND NOT EXISTS(SELECT 1 FROM public.indicator_reporting_snapshots n WHERE n.indicator_id=s.indicator_id AND n.period_start=s.period_start AND n.period_end=s.period_end AND n.version>s.version) $$;
CREATE OR REPLACE FUNCTION public.analytics_approved_results(_org uuid,_start date,_end date) RETURNS TABLE(id uuid,indicator_id uuid,period_start date,period_end date,version integer,snapshot jsonb) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT * FROM app_private.analytics_approved_results(_org,_start,_end) $$;
REVOKE ALL ON FUNCTION app_private.analytics_approved_results(uuid,date,date),public.analytics_approved_results(uuid,date,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION app_private.analytics_approved_results(uuid,date,date),public.analytics_approved_results(uuid,date,date) TO authenticated;
NOTIFY pgrst,'reload schema';